    trimmed_standard_error_text = completed_renewal_job_process.stderr[-2000:]
    return {'renewal_date': renewal_date, 'dry_run': dry_run, 'exit_code': completed_renewal_job_process.returncode, 'stdout': trimmed_standard_output_text, 'stderr': trimmed_standard_error_text}
